<!doctype html><html lang="en"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#1f2937;font-size:10px}h1{color:#14532d;font-size:20px}p{color:#4b5563}table{width:100%;border-collapse:collapse;margin-top:20px}th{background:#dcfce7;text-align:left}th,td{border:1px solid #d1d5db;padding:7px}footer{margin-top:24px;color:#6b7280}.logo{max-width:70px;max-height:70px;float:right}.chart{max-width:100%;max-height:300px;margin:10px 0 18px}</style></head><body><?php if(!empty($centerLogo)&&preg_match('#^assets/img/center-[a-f0-9]{24}\.(?:png|jpg)$#i',$centerLogo)): $logoPath=FCPATH.$centerLogo; if(is_file($logoPath)): ?><img class="logo" src="data:image/<?= strtolower(pathinfo($logoPath,PATHINFO_EXTENSION)) ?>;base64,<?= base64_encode((string)file_get_contents($logoPath)) ?>"><?php endif; endif ?><h1><?= esc($centerName) ?></h1><h2><?= esc($title) ?></h2><p><?= esc($printedAt) ?> · <?= esc(json_encode($filters,JSON_UNESCAPED_UNICODE)) ?></p><?php foreach($charts as $chart): ?><img class="chart" src="<?= esc($chart) ?>"><?php endforeach ?><table><thead><tr><?php foreach(($rows[0]??[]) as $key=>$value): ?><th><?= esc((string)$key) ?></th><?php endforeach ?></tr></thead><tbody><?php foreach($rows as $row): ?><tr><?php foreach($row as $value): ?><td><?= esc((string)$value) ?></td><?php endforeach ?></tr><?php endforeach ?></tbody></table><footer>Confidential child health information. Handle in accordance with the Data Privacy Act of 2012.</footer></body></html>
